import type { EntityInput, PaperInput, TechnologyInput } from "@/lib/schema";
import type { EvidenceGrade, Use } from "@/lib/complementary";

/**
 * Complementary and supportive approaches: what people with cancer use alongside (and sometimes instead of)
 * standard treatment, graded honestly by the evidence. Each approach is a `technology` record so it gets an
 * entity page, hover cards and graph links; the grade travels as a tag `evidence:<grade>` and the purposes
 * live in COMPLEMENTARY_INDEX below, which also grades existing records (exercise, scalp cooling, diets).
 *
 * Grading rules (see src/lib/complementary.ts): strong = consistent randomised trials plus a major guideline
 * recommendation; moderate = trials exist but small, mixed or single-setting; insufficient = no reliable human
 * evidence of benefit; no-benefit = adequately sized trials found nothing; harm = toxicity, interaction, or
 * use in place of standard treatment associated with worse survival. Numbers appear only where the linked
 * primary source states them. UK spelling.
 *
 * Main sources: SIO-ASCO guidelines (pain 2022, anxiety and depression 2023, fatigue 2024), SIO 2017 breast
 * guideline and its 2018 ASCO endorsement, ASCO cannabis guideline 2024, MASCC/ISOO mucositis guidelines 2020,
 * Cochrane reviews, NCI PDQ integrative medicine summaries, MSK About Herbs, and the primary trial papers.
 */

const asOf = "2026-09-10";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
const doi = (label: string, d: string) => ({ label, url: `https://doi.org/${d}` });
const pdq = (label: string, slug: string) => ({ label: `NCI PDQ: ${label}`, url: `https://www.cancer.gov/about-cancer/treatment/cam/hp/${slug}-pdq` });
const herbs = (label: string, slug: string) => ({ label: `MSK About Herbs: ${label}`, url: `https://www.mskcc.org/cancer-care/integrative-medicine/herbs/${slug}` });

const SIO_ASCO_PAIN = doi("SIO-ASCO guideline: integrative medicine for pain management in oncology (JCO 2022)", "10.1200/JCO.22.01357");
const SIO_ASCO_MOOD = doi("SIO-ASCO guideline: integrative oncology care of anxiety and depression (JCO 2023)", "10.1200/JCO.23.00857");
const SIO_ASCO_FATIGUE = doi("SIO-ASCO guideline: integrative oncology care of cancer-related fatigue (JCO 2024)", "10.1200/JCO.24.00575");
const SIO_BREAST_2017 = doi("SIO clinical practice guideline: integrative therapies during and after breast cancer treatment (CA Cancer J Clin 2017)", "10.3322/caac.21397");
const ASCO_ENDORSE_2018 = doi("ASCO endorsement of the SIO breast cancer guideline (JCO 2018)", "10.1200/JCO.2018.79.2721");
const ASCO_CANNABIS_2024 = doi("ASCO guideline: cannabis and cannabinoids in adults with cancer (JCO 2024)", "10.1200/JCO.23.02596");
const MASCC_MUCOSITIS_2020 = doi("MASCC/ISOO clinical practice guidelines for mucositis (Cancer 2020)", "10.1002/cncr.33100");
const JOHNSON_JNCI_2018 = doi("Johnson et al., Use of alternative medicine for cancer and its impact on survival (JNCI 2018)", "10.1093/jnci/djx145");

const SEC = "supportive-care";
const T = (grade: EvidenceGrade, extra: string[] = []) => ["complementary", "supportive-care", `evidence:${grade}`, ...extra];
const tech = (x: Omit<TechnologyInput, "kind" | "asOf">): TechnologyInput => ({ kind: "technology", asOf, ...x });
const paper = (x: Omit<PaperInput, "kind" | "asOf">): PaperInput => ({ kind: "paper", asOf, ...x });

